(8934, 'koKR', 'Jesteś $ggotów:gotowa; do wymiany?', 0),
(8935, 'koKR', 'Jesteś $ggotów:gotowa; do wymiany?', 0),
(8936, 'koKR', 'Jesteś $ggotów:gotowa; do wymiany?', 0),
(8937, 'koKR', 'Jesteś $ggotów:gotowa; do wymiany?', 0),
(8951, 'koKR', '$GWróciłeś:Wróciłaś;, $N. Musisz mi opowiedzieć o wszystkim, czego się $gdowiedziałeś:dowiedziałaś;. Ale najpierw zajmijmy się twoją nagrodą.', 0),
(8952, 'koKR', '$GWróciłeś:Wróciłaś;, $N. Musisz mi opowiedzieć o wszystkim, czego się $gdowiedziałeś:dowiedziałaś;. Ale najpierw zajmijmy się twoją nagrodą.', 0),
(8953, 'koKR', '$GWróciłeś:Wróciłaś;, $N. Musisz mi opowiedzieć o wszystkim, czego się $gdowiedziałeś:dowiedziałaś;. Ale najpierw zajmijmy się twoją nagrodą.', 0),
(8954, 'koKR', '$GWróciłeś:Wróciłaś;, $N. Musisz mi opowiedzieć o wszystkim, czego się $gdowiedziałeś:dowiedziałaś;. Ale najpierw zajmijmy się twoją nagrodą.', 0),
(8955, 'koKR', '$GWróciłeś:Wróciłaś;, $N. Musisz mi opowiedzieć o wszystkim, czego się $gdowiedziałeś:dowiedziałaś;. Ale najpierw zajmijmy się twoją nagrodą.', 0),
(8956, 'koKR', '$GWróciłeś:Wróciłaś;, $N. Musisz mi opowiedzieć o wszystkim, czego się $gdowiedziałeś:dowiedziałaś;. Ale najpierw zajmijmy się twoją nagrodą.', 0),
(8958, 'koKR', '$GWróciłeś:Wróciłaś;, $N. Musisz mi opowiedzieć o wszystkim, czego się $gdowiedziałeś:dowiedziałaś;. Ale najpierw zajmijmy się twoją nagrodą.', 0),
(8959, 'koKR', '$GWróciłeś:Wróciłaś;, $N. Musisz mi opowiedzieć o wszystkim, czego się $gdowiedziałeś:dowiedziałaś;. Ale najpierw zajmijmy się twoją nagrodą.', 0),
(8977, 'koKR', '$GWróciłeś:Wróciłaś;?', 0),
(8999, 'koKR', 'Zgodnie z naszą umową: czy jesteś $ggotów:gotowa; oddać części dzikiego serca w zamian za nowy kaptur i kamizelkę zwierzęcego serca?', 0),
(9000, 'koKR', 'Zgodnie z naszą umową: czy jesteś $ggotów:gotowa; oddać części tropiciela bestii w zamian za nową czapkę i tunikę mistrza bestii?', 0),
(9001, 'koKR', 'Zgodnie z naszą umową: czy jesteś $ggotów:gotowa; oddać części magistra w zamian za nową koronę i szatę czarownika?', 0),
(9002, 'koKR', 'Zgodnie z naszą umową: czy jesteś $ggotów:gotowa; oddać części kuźni światła w zamian za nowy hełm i napierśnik kuźni dusz?', 0),
(9003, 'koKR', 'Zgodnie z naszą umową: czy jesteś $ggotów:gotowa; oddać pobożne części w zamian za nową cnotliwą koronę i szatę?', 0),
(9004, 'koKR', 'Zgodnie z naszą umową: czy jesteś $ggotów:gotowa; oddać części mistrza cieni w zamian za nową czapkę i tunikę mrocznego płaszcza?', 0),
(9005, 'koKR', 'Zgodnie z naszą umową: czy jesteś $ggotów:gotowa; oddać części upiornej mgły w zamian za nową maskę i szatę mgły śmierci?', 0),
(9006, 'koKR', 'Zgodnie z naszą umową: czy jesteś $ggotów:gotowa; oddać części męstwa w zamian za nowy hełm i napierśnik bohaterstwa?', 0),
(10492, 'koKR', '$GPrzyniosłeś:Przyniosłaś; to, o co cię prosiłam, $N?', 0),
(10494, 'koKR', 'Jesteś $ggotów:gotowa; do wymiany?', 0),
(10496, 'koKR', '$GWróciłeś:Wróciłaś;, $N. Musisz mi opowiedzieć o wszystkim, czego się $gdowiedziałeś:dowiedziałaś;. Ale najpierw zajmijmy się twoją nagrodą.', 0),
(10498, 'koKR', 'Zgodnie z naszą umową: czy jesteś $ggotów:gotowa; oddać części dzikiego serca w zamian za nowy kaptur i kamizelkę zwierzęcego serca?', 0),
(12771, 'koKR', 'Witaj, $n. Jeszcze nie widziałem nikogo tak krzepkiego! Próby Rubieży cię zahartowały, $gbracie:siostro;. Przynosisz chlubę swojej rasie!', 0),
(12809, 'koKR', 'Witaj, $n! No proszę! Widzę, że od naszego ostatniego spotkania $gurosłeś:urosłaś; dokładnie o jeden przecinek siedemdziesiąt trzy mikropiędzi. Z całą pewnością to zasługa powietrza Rubieży.', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(1105, 0, 'koKR', 'Wiesz, zawsze chciałem zostać poszukiwaczem, ale urodziłem się z głową do liczb i Gildia uznała, że najlepiej sprawdzę się przy prowadzeniu ksiąg! Nauka, nauka, każdego dnia mojej młodości...', 0),
(1344, 0, 'koKR', 'Choć na tych ruinach mamy teraz zastój, jestem pewien, że nie potrwa on długo. Ale tymczasem przydałby mi się ktoś taki jak ty. Chcesz pomóc Krasnoludzkiej Gildii Odkrywców?', 0),
(1356, 0, 'koKR', 'Jestem w trakcie bardzo ważnego zadania. Sprawy poszukiwaczy. Jeśli nie masz do powiedzenia czegoś równie ważnego, w co wątpię, to wybacz, ale nie mam czasu.', 0),
(2092, 0, 'koKR', 'Machiny oblężnicze to duma każdego pilota!', 0),
(2276, 0, 'koKR', 'Kiedy po raz pierwszy zaproponowano mi urząd sędziego Południowego Brzegu, byłem zachwycony, że tak wcześnie w karierze zasłużyłem na takie stanowisko.$B$BAle teraz, gdy już tu jestem, zastanawiam się, czy nie lepiej byłoby mi przekładać papiery w Wichrogrodzie.', 0),
(2785, 0, 'koKR', 'Odsuń się! Nie podchodź! Mam pełny plecak prochu strzelniczego i nie zawaham się go użyć! Wysadzę nas wszystkich w powietrze!$B$BA, nieważne. Wziąłem cię za kogoś innego...', 0),
(2786, 0, 'koKR', 'Witaj w „Runach i Zgubach Kościochwyta”, $N. Możesz oglądać, ale niczego nie dotykaj.$B$BCzęść tutejszej wiedzy nie jest przeznaczona dla... niewtajemniczonych.', 0),
(2910, 0, 'koKR', 'Dranie napadły na nas w nocy, jak już mieliśmy parę kufli w czubie. Inaczej dalibyśmy im radę, możesz być $gpewien:pewna;.$B$BWszyscy nie żyją... oprócz kilku z nas.', 0),
(4453, 0, 'koKR', 'Uważaj, gdzie stawiasz stopę, $gpanie:pani;. Nie każdy został obdarzony tak słusznym wzrostem, jakim może się pochwalić $r.', 0),
(5637, 0, 'koKR', 'Miło cię poznać, $N. Zwą mnie Roetten. Stoję na czele Odzyskiwaczy sp. z o.o.$B$BJa i moja gildia specjalizujemy się w odzyskiwaniu zagubionych dóbr. Zwykle najmujemy dzielnych poszukiwaczy przygód i wysyłamy ich, żeby wykonali zadania za tych, którzy nie mogą albo nie mają na to czasu.', 0),
(5638, 0, 'koKR', 'Mam tu w Mrocznym Pustkowiu kupę roboty, $N. Roetten chce, żebyśmy zebrali odczynniki dla jednego z naszych klientów i przynieśli trochę tych zagubionych rzeczy.$B$BSkoro już $gprzyszedłeś:przyszłaś; pomóc, to może zaczniemy?', 0),
(6031, 0, 'koKR', 'Niektórzy nie wytrzymują żaru Wielkiej Kuźni, ale jak dla mnie jest w sam raz. I nie ma lepszego miejsca na porządną robotę kowalską.', 0),
(8256, 0, 'koKR', 'Witaj, $N.', 0);
